#!/usr/bin/env python3
"""
Round 123b (culprits-tiles-more), 2 October 2026. Upload after round122b_tiles.py.

- scripts/natural_hazards.py: NASA EONET read year by year; the Smithsonian
  volcano layer name read from its own list; landslides from NASA's other
  services, then its export file; a part never built is tried daily; GDACS
  alert levels said in words.
- scripts/iuu_vessels.py: page headings read level by level (the whole page
  was being read as one heading, so no flag or position was found); reads
  TMT's own spreadsheet from iuu/download/ when it is there.
- scripts/env_enforcement.py: IBAMA's embargo file at its new address; a
  second, lighter try at the infraction tiles; an unbuilt layer tried daily.
- scripts/berkeley_warming.py (new): warmer and cooler than 1951-1980, each
  year from 2000, from Berkeley Earth's gridded file.
- scripts/envlaw.py (new) and envlaw/ (a first build): the environmental law
  atlas index as places and countries.
- scripts/isds_unctad.py (new): UNCTAD's full list of investor-state cases,
  with the Energy Charter Treaty ones.
- scripts/water_culprits.py (new): how much of each country's renewable
  water farming alone takes (FAO AQUASTAT via the World Bank).
- iuu/download/README.md (new).

Every file is written whole, and only if it differs.
"""
import base64, pathlib

FILES = {
    'scripts/natural_hazards.py': '',
    'scripts/iuu_vessels.py': '',
    'scripts/env_enforcement.py': '',
    'scripts/berkeley_warming.py': '',
    'scripts/envlaw.py': '',
    'scripts/isds_unctad.py': '',
    'scripts/water_culprits.py': '',
    'envlaw/jurisdictions.geojson': '',
    'envlaw/countries.json': '',
    'envlaw/build.json': '',
    'iuu/download/README.md': '',
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"  {name}: already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"  {name}: written")


if __name__ == "__main__":
    main()
